{"op":"add","path":"/root","value":"wizard"}
{"op":"add","path":"/elements/wizard","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg","align":"stretch"},"children":["header","progress-row","step-account","step-preferences","step-done"]}}
{"op":"add","path":"/elements/header","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["title","subtitle"]}}
{"op":"add","path":"/elements/title","value":{"type":"Heading","props":{"text":"Welcome to Pulseboard","level":"h1"},"children":[]}}
{"op":"add","path":"/elements/subtitle","value":{"type":"Text","props":{"text":"Set up your workspace in three quick steps. You can change anything later in Settings.","variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/progress-row","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"children":["progress-bar","steps-labels"]}}
{"op":"add","path":"/elements/progress-bar","value":{"type":"Progress","props":{"label":"Step progress","value":{"$cond":{"$state":"/step","eq":"account"},"$then":33,"$else":{"$cond":{"$state":"/step","eq":"preferences"},"$then":66,"$else":100}}},"children":[]}}
{"op":"add","path":"/elements/steps-labels","value":{"type":"Stack","props":{"direction":"horizontal","gap":"md","align":"center"},"children":["step-badge-1","step-badge-2","step-badge-3"]}}
{"op":"add","path":"/elements/step-badge-1","value":{"type":"Badge","props":{"text":"1. Account","variant":{"$cond":{"$state":"/step","eq":"account"},"$then":"default","$else":{"$cond":{"$state":"/step","eq":"preferences"},"$then":"outline","$else":"outline"}}},"children":[]}}
{"op":"add","path":"/elements/step-badge-2","value":{"type":"Badge","props":{"text":"2. Preferences","variant":{"$cond":{"$state":"/step","eq":"preferences"},"$then":"default","$else":"outline"}},"visible":{"$or":[{"$state":"/step","eq":"preferences"},{"$state":"/step","eq":"done"}]},"children":[]}}
{"op":"add","path":"/elements/step-badge-3","value":{"type":"Badge","props":{"text":"3. Done","variant":{"$cond":{"$state":"/step","eq":"done"},"$then":"default","$else":"outline"}},"visible":{"$state":"/step","eq":"done"},"children":[]}}
{"op":"add","path":"/elements/step-account","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"visible":{"$or":[{"$state":"/step","eq":"account"},{"$state":"/step","not":true}]},"children":["account-card","account-nav"]}}
{"op":"add","path":"/elements/account-card","value":{"type":"Card","props":{"title":"Create your account","description":"Tell us who you are. We'll use this to personalize your dashboard."},"children":["name-input","email-input","password-input","terms-check"]}}
{"op":"add","path":"/elements/name-input","value":{"type":"Input","props":{"label":"Full name","placeholder":"Ada Lovelace","type":"text","value":{"$bindState":"/account/name"}},"children":[]}}
{"op":"add","path":"/elements/email-input","value":{"type":"Input","props":{"label":"Work email","placeholder":"ada@company.com","type":"email","value":{"$bindState":"/account/email"}},"children":[]}}
{"op":"add","path":"/elements/password-input","value":{"type":"Input","props":{"label":"Password","placeholder":"At least 8 characters","type":"password","value":{"$bindState":"/account/password"}},"children":[]}}
{"op":"add","path":"/elements/terms-check","value":{"type":"Checkbox","props":{"label":"I agree to the Terms of Service and Privacy Policy","checked":{"$bindState":"/account/agreed"}},"children":[]}}
{"op":"add","path":"/elements/account-nav","value":{"type":"Stack","props":{"direction":"horizontal","gap":"md","align":"center"},"children":["account-spacer","back-btn-1","next-btn-1"]}}
{"op":"add","path":"/elements/account-spacer","value":{"type":"Stack","props":{"direction":"horizontal"},"children":[]}}
{"op":"add","path":"/elements/back-btn-1","value":{"type":"Button","props":{"label":"Back","variant":"outline","size":"default"},"visible":false,"on":{"press":{"action":"setState","params":{"statePath":"/step","value":"account"}}},"children":[]}}
{"op":"add","path":"/elements/next-btn-1","value":{"type":"Button","props":{"label":"Next: Preferences →","variant":"default","size":"lg"},"on":{"press":{"action":"setState","params":{"statePath":"/step","value":"preferences"}}},"children":[]}}
{"op":"add","path":"/elements/step-preferences","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"visible":{"$state":"/step","eq":"preferences"},"children":["prefs-card","prefs-nav"]}}
{"op":"add","path":"/elements/prefs-card","value":{"type":"Card","props":{"title":"Tune your workspace","description":"Choose how Pulseboard should look and what to track first."},"children":["role-select","team-size-select","theme-radio","notif-switch","digest-switch"]}}
{"op":"add","path":"/elements/role-select","value":{"type":"Select","props":{"label":"What best describes your role?","placeholder":"Select a role","options":["Product Manager","Engineer","Designer","Data Analyst","Founder","Other"],"value":{"$bindState":"/prefs/role"}},"children":[]}}
{"op":"add","path":"/elements/team-size-select","value":{"type":"Select","props":{"label":"Team size","placeholder":"Select team size","options":["Just me","2–10","11–50","51–200","200+"],"value":{"$bindState":"/prefs/teamSize"}},"children":[]}}
{"op":"add","path":"/elements/theme-radio","value":{"type":"RadioGroup","props":{"label":"Preferred theme","options":["Light","Dark","System"],"value":{"$bindState":"/prefs/theme"}},"children":[]}}
{"op":"add","path":"/elements/notif-switch","value":{"type":"Switch","props":{"label":"Product notifications","description":"Get in-app alerts when metrics change significantly.","checked":{"$bindState":"/prefs/notifications"}},"children":[]}}
{"op":"add","path":"/elements/digest-switch","value":{"type":"Switch","props":{"label":"Weekly email digest","description":"A summary of your key metrics every Monday morning.","checked":{"$bindState":"/prefs/digest"}},"children":[]}}
{"op":"add","path":"/elements/prefs-nav","value":{"type":"Stack","props":{"direction":"horizontal","gap":"md","align":"center"},"children":["back-btn-2","prefs-spacer","next-btn-2"]}}
{"op":"add","path":"/elements/back-btn-2","value":{"type":"Button","props":{"label":"← Back","variant":"outline","size":"default"},"on":{"press":{"action":"setState","params":{"statePath":"/step","value":"account"}}},"children":[]}}
{"op":"add","path":"/elements/prefs-spacer","value":{"type":"Stack","props":{"direction":"horizontal"},"children":[]}}
{"op":"add","path":"/elements/next-btn-2","value":{"type":"Button","props":{"label":"Finish setup →","variant":"default","size":"lg"},"on":{"press":{"action":"setState","params":{"statePath":"/step","value":"done"}}},"children":[]}}
{"op":"add","path":"/elements/step-done","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"visible":{"$state":"/step","eq":"done"},"children":["done-card","done-nav"]}}
{"op":"add","path":"/elements/done-card","value":{"type":"Card","props":{"title":"You're all set! 🎉","description":"Here's a summary of your new workspace. Press Launch to jump in."},"children":["summary-sep","summary-list","summary-alert"]}}
{"op":"add","path":"/elements/summary-sep","value":{"type":"Separator","props":{},"children":[]}}
{"op":"add","path":"/elements/summary-list","value":{"type":"List","props":{"items":[{"$template":"Account: ${name} <${email}>"},{"$template":"Role: ${role} · Team size: ${teamSize}"},{"$template":"Theme: ${theme}"},{"$template":"Notifications: ${notifState} · Weekly digest: ${digestState}"}]},"children":[]}}
{"op":"add","path":"/elements/summary-alert","value":{"type":"Alert","props":{"title":"Workspace ready","description":"You can update any of these choices anytime under Settings → Workspace.","variant":"default"},"children":[]}}
{"op":"add","path":"/elements/done-nav","value":{"type":"Stack","props":{"direction":"horizontal","gap":"md","align":"center"},"children":["back-btn-3","done-spacer","launch-btn"]}}
{"op":"add","path":"/elements/back-btn-3","value":{"type":"Button","props":{"label":"← Back","variant":"outline","size":"default"},"on":{"press":{"action":"setState","params":{"statePath":"/step","value":"preferences"}}},"children":[]}}
{"op":"add","path":"/elements/done-spacer","value":{"type":"Stack","props":{"direction":"horizontal"},"children":[]}}
