{"op":"add","path":"/elements/digest-switch/watch","value":{"/prefs/digest":{"action":"setState","params":{"statePath":"/digestState","value":{"$cond":{"$state":"/prefs/digest"},"$then":"On","$else":"Off"}}}}}
